+// Keep the largest legal take size on each board, alongside all buys/reserves.
+// Ordinary and replenished boards are filtered independently.
+func maximumTokenTakes(moves []simMove) []simMove {
+	count := func(action uint32) int {
+		if action&3 != 0 {
+			return 0
+		}
+		if action>>12&31 != 0 {
+			return 3
+		}
+		if action>>7&31 != 0 {
+			return 2
+		}
+		return 1
+	}
+	maximum := 0
+	for _, m := range moves {
+		maximum = max(maximum, count(m.action))
+	}
+	out := moves[:0]
+	for _, m := range moves {
+		if n := count(m.action); n == 0 || n == maximum {
+			out = append(out, m)
+		}
+	}
+	return out
